// 由 build-feature.mjs 从 src/pull.css 抽出（不要手改）
export const CSS = "/* 游戏数据采集 · 面板样式（定稿原型 v5）\r\n *\r\n * 与 3D 预览面板（`preview/app.css`）「同一套令牌层」，两块面板在宿主里长得是一家：\r\n *   ① 令牌单一来源、不硬编码颜色/间距：颜色走 `--mm-*`，`--mm-*` 优先取宿主主题令牌 `--theme-*`；\r\n *      CSS 自定义属性穿过 Shadow DOM 继承 ⇒ 自动跟随宿主浅色/深色。\r\n *   ② 间距只允许 4pt 倍数；圆角同页 3 档（控件 8 / 卡片 12 / 胶囊 full）；字号阶梯 12/14/16/20。\r\n *   ③ 组件 7 态（默认 / hover / active / focus-visible / disabled / loading / error）；\r\n *      `:focus-visible` 一律可见；动效尊重 `prefers-reduced-motion`。\r\n *   ④ 正文 ≥4.5:1、控件边界 ≥3:1（从正文色派生，见 `--mm-ctl-border`）。\r\n */\r\n\r\n:host{ display: block; height: 100%; min-height: 0; overflow: hidden; }\r\n.mcpull-wrap{ display: flex; flex-direction: column; height: 100%; min-height: 0; }\r\n\r\n.mcpull-root{\r\n  /* ============ 颜色：宿主主题优先，浅色兜底 ============ */\r\n  --mm-canvas: var(--theme-canvas, #eef0f3);\r\n  --mm-surface: var(--theme-surface, #ffffff);\r\n  --mm-bg-2: var(--theme-bg-secondary, #f4f5f7);\r\n  --mm-bg-3: var(--theme-bg-tertiary, #e6e9ed);\r\n  --mm-line: var(--theme-line, #e4e7ec);\r\n  --mm-text-1: var(--theme-text-primary, var(--theme-text, #181a1f));\r\n  --mm-text-2: var(--theme-text-secondary, #5d6572);\r\n  --mm-muted: var(--theme-muted, #8c95a3);\r\n  --mm-accent: var(--theme-accent, #2563eb);\r\n  --mm-action: var(--theme-action, #1e4fd0);\r\n  --mm-on-action: var(--theme-on-action, #ffffff);\r\n  --mm-ok: #157f3e;\r\n  --mm-warn: #a05708;\r\n  --mm-err: #bb3a2c;\r\n  --mm-ctl-line: var(--theme-control-border, #c8cdd7);\r\n  --mm-accent-tint: color-mix(in srgb, var(--mm-accent) 12%, var(--mm-surface));\r\n  --mm-ok-tint: color-mix(in srgb, var(--mm-ok) 12%, var(--mm-surface));\r\n  --mm-warn-tint: color-mix(in srgb, var(--mm-warn) 12%, var(--mm-surface));\r\n  --mm-err-tint: color-mix(in srgb, var(--mm-err) 12%, var(--mm-surface));\r\n\r\n  /* 间距 / 圆角 / 字号 / 动效 */\r\n  --sp-1: 4px; --sp-2: 8px; --sp-3: 12px; --sp-4: 16px; --sp-6: 24px; --sp-8: 32px;\r\n  --r-ctl: 8px; --r-card: 12px; --r-full: 9999px;\r\n  --fs-xs: 12px; --fs-sm: 14px; --fs-md: 16px; --fs-lg: 20px;\r\n  --font-ui: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\r\n  --font-num: \"SF Mono\", \"JetBrains Mono\", Consolas, \"Cascadia Mono\", monospace;\r\n  --sh-sm: 0 1px 2px rgba(15, 23, 42, .06);\r\n  --sh-pop: 0 8px 28px rgba(18, 25, 38, .16);\r\n  --t-fast: 130ms; --t-base: 240ms;\r\n  --ease: cubic-bezier(.2, .8, .2, 1);\r\n\r\n  color-scheme: light dark;\r\n  display: flex; flex-direction: column;\r\n  height: 100%; min-height: 0; overflow: auto;\r\n  padding: var(--sp-4) var(--sp-6) var(--sp-6);\r\n  background: var(--mm-surface); color: var(--mm-text-1);\r\n  font: var(--fs-sm)/1.6 var(--font-ui);\r\n}\r\n.mcpull-root *{ box-sizing: border-box; }\r\n.mcpull-root .num{ font-family: var(--font-num); font-variant-numeric: tabular-nums; }\r\n.mcpull-root .mono{ font-family: var(--font-num); }\r\n.hint-inline{ font-size: var(--fs-xs); color: var(--mm-muted); }\r\n\r\n/* ---------- 头部 ---------- */\r\n.p-head{ display: flex; align-items: flex-start; gap: var(--sp-3); margin-bottom: var(--sp-3); }\r\n.p-head .tt{ flex: 1; min-width: 0; }\r\n.p-head h1{ margin: 0; font-size: 17px; font-weight: 700; letter-spacing: .2px; }\r\n.p-head p{ margin: 3px 0 0; color: var(--mm-text-2); font-size: 12.5px; }\r\n\r\n/* ---------- 目标实例选择器 ---------- */\r\n.inst-pick{ position: relative; flex: 0 0 auto; margin-top: 2px; }\r\n.inst-btn{\r\n  display: flex; align-items: center; gap: var(--sp-2);\r\n  font: inherit; font-size: 12px; color: var(--mm-text-2); cursor: pointer;\r\n  border: 1px solid var(--mm-ctl-line); border-radius: var(--r-full);\r\n  padding: var(--sp-1) var(--sp-3); background: var(--mm-bg-2); white-space: nowrap;\r\n  transition: background var(--t-fast), border-color var(--t-fast);\r\n}\r\n.inst-btn:hover{ background: var(--mm-bg-3); }\r\n.inst-btn:focus-visible{ outline: 2px solid var(--mm-accent); outline-offset: 2px; }\r\n.inst-btn .ip-label{ color: var(--mm-muted); font-size: 11px; }\r\n.inst-btn .ip-name{ color: var(--mm-text-1); font-weight: 600; }\r\n.inst-btn .ip-ver{ font-family: var(--font-num); font-size: 11px; color: var(--mm-text-2); }\r\n.inst-btn .ip-caret{ color: var(--mm-muted); font-size: 10px; }\r\n.inst-btn[aria-expanded=\"true\"] .ip-caret{ transform: rotate(180deg); }\r\n.inst-menu{\r\n  position: absolute; right: 0; top: calc(100% + 6px); z-index: 30;\r\n  min-width: 340px; max-width: 440px;\r\n  background: var(--mm-surface); border: 1px solid var(--mm-line); border-radius: var(--r-card);\r\n  box-shadow: var(--sh-pop); padding: 6px;\r\n}\r\n.inst-menu[hidden]{ display: none; }\r\n.inst-item{ display: flex; align-items: center; gap: var(--sp-3); padding: 9px 10px; border-radius: var(--r-ctl); cursor: pointer; }\r\n.inst-item:hover{ background: var(--mm-bg-2); }\r\n.inst-item.active{ background: var(--mm-accent-tint); }\r\n.inst-item .ii-mark{\r\n  width: 26px; height: 26px; flex: 0 0 26px; border-radius: 7px;\r\n  display: flex; align-items: center; justify-content: center;\r\n  background: var(--mm-bg-3); color: var(--mm-text-2); font-size: 11px; font-weight: 700; font-family: var(--font-num);\r\n}\r\n.inst-item.active .ii-mark{ background: var(--mm-accent); color: var(--mm-on-action); }\r\n.inst-item .ii-info{ flex: 1; min-width: 0; }\r\n.inst-item .ii-t{ font-size: 12.5px; font-weight: 600; }\r\n.inst-item .ii-s{ font-size: 11px; color: var(--mm-text-2); margin-top: 1px; word-break: break-all; }\r\n.inst-item .ii-badge{\r\n  flex: 0 0 auto; font-size: 10.5px; font-weight: 600; padding: 2px 8px;\r\n  border-radius: var(--r-full); border: 1px solid transparent; white-space: nowrap;\r\n}\r\n.ii-badge.ok{ color: var(--mm-ok); border-color: color-mix(in srgb, var(--mm-ok) 45%, transparent); background: var(--mm-ok-tint); }\r\n.ii-badge.warn{ color: var(--mm-warn); border-color: color-mix(in srgb, var(--mm-warn) 45%, transparent); background: var(--mm-warn-tint); }\r\n.ii-badge.no{ color: var(--mm-muted); border-color: var(--mm-ctl-line); background: var(--mm-bg-2); }\r\n.inst-menu .menu-note{ font-size: 10.5px; color: var(--mm-muted); padding: 7px 10px 4px; border-top: 1px solid var(--mm-line); margin-top: 4px; }\r\n.menu-scan{ display: flex; align-items: center; gap: var(--sp-2); font-size: 10.5px; color: var(--mm-muted); padding: 7px 10px 4px; border-top: 1px solid var(--mm-line); margin-top: 4px; }\r\n.menu-scan .sp{ flex: 1; }\r\n.menu-scan button{\r\n  font: inherit; font-size: 10.5px; padding: 3px 9px; cursor: pointer;\r\n  border: 1px solid var(--mm-ctl-line); border-radius: var(--r-full);\r\n  background: var(--mm-surface); color: var(--mm-text-2);\r\n}\r\n.menu-scan button:hover{ background: var(--mm-bg-2); color: var(--mm-text-1); }\r\n\r\n/* ---------- 扫描路径 ---------- */\r\n.scan-paths{ display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }\r\n.scan-paths .pth{\r\n  display: flex; align-items: center; gap: var(--sp-2); font-size: 11.5px; color: var(--mm-text-2);\r\n  padding: 6px 10px; background: var(--mm-bg-2); border: 1px solid var(--mm-line); border-radius: var(--r-ctl);\r\n}\r\n.scan-paths .pth .dot2{ width: 5px; height: 5px; border-radius: 50%; background: var(--mm-muted); flex: 0 0 5px; }\r\n.spin-lg{\r\n  width: 15px; height: 15px; border-radius: 50%; display: inline-block; vertical-align: -2px; margin-right: 7px;\r\n  border: 2px solid var(--mm-accent); border-right-color: transparent; animation: mcpull-rot .7s linear infinite;\r\n}\r\n\r\n/* ---------- 状态行 ---------- */\r\n.status-strip{\r\n  display: flex; align-items: center; gap: 10px;\r\n  padding: 9px 14px; font-size: 13px; font-weight: 600;\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-ctl); background: var(--mm-bg-2);\r\n}\r\n.status-strip .dot{ width: 8px; height: 8px; border-radius: 50%; flex: 0 0 8px; background: var(--mm-muted); }\r\n.status-strip.s-run .dot{ background: var(--mm-accent); animation: mcpull-pulse 1.6s var(--ease) infinite; }\r\n.status-strip.s-ok .dot{ background: var(--mm-ok); }\r\n.status-strip.s-wait .dot{ background: var(--mm-warn); }\r\n.status-strip .sub{ margin-left: auto; font-weight: 400; color: var(--mm-text-2); font-size: 12px; }\r\n@keyframes mcpull-pulse{ 0%,100%{ box-shadow: 0 0 0 0 transparent; } 50%{ box-shadow: 0 0 0 5px var(--mm-accent-tint); } }\r\n\r\n/* ---------- 步骤线 ---------- */\r\n.steps{ display: flex; padding: var(--sp-4) var(--sp-2) 0; margin: 0; list-style: none; }\r\n.step{ flex: 1; display: flex; flex-direction: column; align-items: center; position: relative; min-width: 0; }\r\n.step::before{ content: \"\"; position: absolute; top: 15px; left: -50%; width: 100%; height: 2px; background: var(--mm-line); z-index: 0; }\r\n.step:first-child::before{ display: none; }\r\n.step.done::before, .step.active::before{ background: var(--mm-accent); }\r\n.step .mark{\r\n  z-index: 1; width: 30px; height: 30px; border-radius: 50%;\r\n  display: flex; align-items: center; justify-content: center;\r\n  font-size: 13px; font-weight: 700; font-family: var(--font-num);\r\n  background: var(--mm-surface); border: 2px solid var(--mm-ctl-line); color: var(--mm-muted);\r\n  transition: all var(--t-base) var(--ease);\r\n}\r\n.step .mark svg{ width: 14px; height: 14px; display: block; }\r\n.step.active .mark{ border-color: var(--mm-accent); color: var(--mm-accent); background: var(--mm-accent-tint); box-shadow: 0 0 0 4px var(--mm-accent-tint); }\r\n.step.done .mark{ border-color: var(--mm-accent); background: var(--mm-accent); color: var(--mm-on-action); }\r\n.step .lab{ margin-top: 7px; font-size: 12px; font-weight: 600; color: var(--mm-text-2); text-align: center; }\r\n.step.active .lab{ color: var(--mm-text-1); }\r\n.step .st{ margin-top: 1px; font-size: 11px; color: var(--mm-muted); text-align: center; padding: 0 var(--sp-1); }\r\n.step.active .st{ color: var(--mm-accent); }\r\n\r\n/* ---------- 当前步骤卡 ---------- */\r\n.stage{ padding: var(--sp-4) 0 0; }\r\n.stage-card{\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-card); background: var(--mm-surface);\r\n  box-shadow: var(--sh-sm); padding: var(--sp-4);\r\n}\r\n.stage-card .kicker{ font-size: 11px; font-weight: 700; letter-spacing: 1px; color: var(--mm-accent); text-transform: uppercase; margin-bottom: var(--sp-1); }\r\n.stage-card h2{ margin: 0 0 var(--sp-2); font-size: 15.5px; font-weight: 700; display: flex; align-items: center; }\r\n.stage-card .desc{ margin: 0; color: var(--mm-text-2); font-size: 13px; }\r\n.stage-card .cta-row{ display: flex; align-items: center; gap: 10px; margin-top: var(--sp-4); flex-wrap: wrap; }\r\n.stage-card .meta{\r\n  margin-top: var(--sp-3); padding-top: 10px; border-top: 1px dashed var(--mm-line);\r\n  display: flex; gap: var(--sp-6); flex-wrap: wrap; font-size: 12px; color: var(--mm-text-2);\r\n}\r\n.stage-card .meta b{ color: var(--mm-text-1); font-weight: 600; }\r\n\r\n/* 探针适配行 */\r\n.probe-line{\r\n  display: flex; align-items: center; gap: 9px; flex-wrap: wrap;\r\n  margin-top: var(--sp-3); padding: 9px var(--sp-3);\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-ctl); background: var(--mm-bg-2);\r\n  font-size: 12px; color: var(--mm-text-2);\r\n}\r\n.probe-line .pl-label{ font-weight: 600; color: var(--mm-text-2); }\r\n.probe-line b{ font-size: 11.5px; color: var(--mm-text-1); font-weight: 600; }\r\n.probe-line .pl-why{ font-size: 11px; color: var(--mm-muted); }\r\n.probe-line .sp{ flex: 1; }\r\n.probe-list{ margin-top: var(--sp-2); border: 1px solid var(--mm-line); border-radius: var(--r-ctl); padding: var(--sp-2) 10px; font-size: 12px; background: var(--mm-surface); }\r\n.probe-list[hidden]{ display: none; }\r\n.probe-list .pr-item{ padding: 4px 2px; font-size: 11.5px; font-family: var(--font-num); color: var(--mm-text-1); }\r\n.probe-list .pr-note{ font-size: 10.5px; color: var(--mm-muted); padding: 5px 2px 2px; border-top: 1px dashed var(--mm-line); margin-top: 5px; }\r\n.probe-ok{\r\n  display: flex; align-items: center; gap: var(--sp-2); flex-wrap: wrap;\r\n  margin-top: var(--sp-3); padding: var(--sp-2) var(--sp-3);\r\n  border: 1px solid color-mix(in srgb, var(--mm-ok) 35%, transparent);\r\n  border-radius: var(--r-ctl); background: var(--mm-ok-tint);\r\n  font-size: 11.5px; color: var(--mm-text-1);\r\n}\r\n.probe-ok svg{ width: 14px; height: 14px; color: var(--mm-ok); flex: 0 0 14px; }\r\n.probe-ok .sp{ flex: 1; }\r\n\r\n/* ---------- note ---------- */\r\n.note{\r\n  border-radius: var(--r-ctl); padding: 10px var(--sp-3); font-size: 12.5px; line-height: 1.55;\r\n  display: flex; gap: 9px; align-items: flex-start; margin-top: var(--sp-3);\r\n}\r\n.note svg{ width: 15px; height: 15px; flex: 0 0 15px; margin-top: 2px; }\r\n.note.warn{ background: var(--mm-warn-tint); color: var(--mm-text-1); border: 1px solid color-mix(in srgb, var(--mm-warn) 40%, transparent); }\r\n.note.warn svg{ color: var(--mm-warn); }\r\n.note.err{ background: var(--mm-err-tint); color: var(--mm-text-1); border: 1px solid color-mix(in srgb, var(--mm-err) 35%, transparent); }\r\n.note.err svg{ color: var(--mm-err); }\r\n.note.ok{ background: var(--mm-ok-tint); color: var(--mm-text-1); border: 1px solid color-mix(in srgb, var(--mm-ok) 35%, transparent); }\r\n.note.ok svg{ color: var(--mm-ok); }\r\n\r\n/* ---------- 按钮（7 态） ---------- */\r\n.btn{\r\n  display: inline-flex; align-items: center; gap: 7px;\r\n  font: inherit; font-size: 13px; font-weight: 600;\r\n  padding: 9px var(--sp-4); border-radius: var(--r-ctl); cursor: pointer;\r\n  border: 1px solid var(--mm-ctl-line); background: var(--mm-surface); color: var(--mm-text-1);\r\n  transition: background var(--t-fast), border-color var(--t-fast), transform var(--t-fast), opacity var(--t-fast);\r\n}\r\n.btn:hover:not(:disabled){ background: var(--mm-bg-2); }\r\n.btn:active:not(:disabled){ transform: scale(.975); }\r\n.btn:focus-visible{ outline: 2px solid var(--mm-accent); outline-offset: 2px; }\r\n.btn:disabled{ opacity: .45; cursor: not-allowed; }\r\n.btn.primary{ background: var(--mm-accent); border-color: var(--mm-accent); color: var(--mm-on-action); }\r\n.btn.primary:hover:not(:disabled){ background: var(--mm-action); border-color: var(--mm-action); }\r\n.btn.ghost{ border-color: transparent; background: transparent; color: var(--mm-text-2); }\r\n.btn.ghost:hover:not(:disabled){ background: var(--mm-bg-2); color: var(--mm-text-1); }\r\n.btn.danger{ color: var(--mm-err); border-color: color-mix(in srgb, var(--mm-err) 45%, transparent); background: transparent; }\r\n.btn.danger:hover:not(:disabled){ background: var(--mm-err-tint); }\r\n.btn .spin{ width: 13px; height: 13px; flex: 0 0 13px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: mcpull-rot .7s linear infinite; }\r\n.btn.sm{ font-size: 12px; padding: 6px var(--sp-3); }\r\n@keyframes mcpull-rot{ to{ transform: rotate(360deg); } }\r\n\r\n/* ---------- 进度 ---------- */\r\n.prog{ margin-top: var(--sp-4); }\r\n.prog .bar{ height: 8px; border-radius: var(--r-full); background: var(--mm-bg-3); overflow: hidden; }\r\n.prog .bar i{ display: block; height: 100%; width: 0%; border-radius: var(--r-full); background: var(--mm-accent); transition: width 120ms linear; }\r\n.prog .nums{ display: flex; justify-content: space-between; margin-top: 7px; font-size: 12px; color: var(--mm-text-2); }\r\n.prog .nums .num{ color: var(--mm-text-1); }\r\n\r\n/* ---------- 结果横幅 ---------- */\r\n.banner{\r\n  border: 1px solid color-mix(in srgb, var(--mm-ok) 40%, transparent); background: var(--mm-ok-tint);\r\n  border-radius: var(--r-ctl); padding: var(--sp-3); margin-top: var(--sp-3);\r\n  display: flex; align-items: center; gap: var(--sp-3);\r\n}\r\n.banner .big{ font-family: var(--font-num); font-size: 22px; font-weight: 700; color: var(--mm-ok); line-height: 1; }\r\n.banner .txt{ font-size: 12.5px; color: var(--mm-text-1); line-height: 1.5; }\r\n\r\n/* ---------- 数据包 ---------- */\r\n.sect{ padding: var(--sp-4) 0 0; }\r\n.sect-head{ display: flex; align-items: baseline; gap: 10px; margin-bottom: 10px; }\r\n.sect-head h3{ margin: 0; font-size: 13px; font-weight: 700; letter-spacing: .3px; }\r\n.sect-head .hint{ font-size: 11.5px; color: var(--mm-text-2); }\r\n.packs{ display: flex; flex-direction: column; gap: var(--sp-2); }\r\n.pack-empty{\r\n  display: flex; align-items: center; gap: var(--sp-3);\r\n  border: 1px dashed var(--mm-ctl-line); border-radius: var(--r-ctl); padding: var(--sp-3); background: var(--mm-bg-2); color: var(--mm-text-2);\r\n}\r\n.pack-empty .pe-ico{\r\n  width: 28px; height: 28px; flex: 0 0 28px; border-radius: 8px;\r\n  border: 1px dashed var(--mm-ctl-line); display: flex; align-items: center; justify-content: center;\r\n  color: var(--mm-muted); font-size: 15px; line-height: 1;\r\n}\r\n.pack-empty .pe-t{ font-size: 13px; font-weight: 600; color: var(--mm-text-2); }\r\n.pack-empty .pe-sub{ font-size: 11.5px; margin-top: 2px; color: var(--mm-muted); }\r\n.pack{\r\n  display: flex; align-items: center; gap: var(--sp-3);\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-ctl);\r\n  padding: 11px var(--sp-3); cursor: pointer; background: var(--mm-surface);\r\n  transition: border-color var(--t-fast), background var(--t-fast), box-shadow var(--t-fast);\r\n}\r\n.pack:hover{ background: var(--mm-bg-2); }\r\n.pack.active{ border-color: var(--mm-accent); box-shadow: inset 0 0 0 1px var(--mm-accent); background: var(--mm-accent-tint); }\r\n.pack .radio{ width: 16px; height: 16px; border-radius: 50%; flex: 0 0 16px; border: 2px solid var(--mm-ctl-line); position: relative; }\r\n.pack.active .radio{ border-color: var(--mm-accent); }\r\n.pack.active .radio::after{ content: \"\"; position: absolute; inset: 2.5px; border-radius: 50%; background: var(--mm-accent); }\r\n.pack .info{ flex: 1; min-width: 0; }\r\n.pack .t{ font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }\r\n.pack .t .cur{ font-size: 10.5px; font-weight: 700; letter-spacing: .3px; color: var(--mm-accent); border: 1px solid var(--mm-accent); border-radius: var(--r-full); padding: 0 7px; background: var(--mm-surface); }\r\n.pack .t .src{ font-size: 10.5px; font-weight: 400; color: var(--mm-text-2); border: 1px solid var(--mm-line); border-radius: var(--r-full); padding: 0 7px; background: var(--mm-bg-2); }\r\n.pack .t .src.probe{ border-color: var(--mm-accent); color: var(--mm-accent); background: var(--mm-accent-tint); }\r\n/* ★ 2026-10-12 B1：属性可信度徽章（未知 / 不可信）—— 用 warn 色，与「游戏内真渲染」的 accent 区分开。\r\n   §0.6 要求「失败必须可见」：宁可显眼地标出来，也不要让用户把占位值当实测值。 */\r\n.pack .t .attr-badge{ border-color: var(--mm-warn, #d08b2c); color: var(--mm-warn, #d08b2c); background: transparent; }\r\n.pack .sub{ font-size: 11.5px; color: var(--mm-text-2); margin-top: 2px; }\r\n.pack-wrap{ display: flex; flex-direction: column; }\r\n.pack-wrap .pack-del{ flex: 0 0 auto; }\r\n.pack-actions-wrap{ }\r\n.pack-actions{ display: flex; align-items: center; gap: var(--sp-2); margin-top: var(--sp-2); }\r\n.pack-actions .sp{ flex: 1; }\r\n.clear-confirm{\r\n  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;\r\n  border: 1px solid color-mix(in srgb, var(--mm-err) 40%, transparent); background: var(--mm-err-tint);\r\n  border-radius: var(--r-ctl); padding: 10px var(--sp-3); margin-top: var(--sp-2); font-size: 12.5px;\r\n}\r\n.clear-confirm .sp{ flex: 1; }\r\n\r\n/* ---------- 自动采集 ---------- */\r\n.auto-row{ display: flex; align-items: center; gap: var(--sp-3); border: 1px solid var(--mm-line); border-radius: var(--r-ctl); padding: var(--sp-3); background: var(--mm-surface); }\r\n.auto-row .info{ flex: 1; min-width: 0; }\r\n.auto-row .t{ font-size: 13px; font-weight: 600; }\r\n.auto-row .sub{ font-size: 11.5px; color: var(--mm-text-2); margin-top: 2px; display: flex; align-items: center; gap: 6px; }\r\n.live-dot{ width: 7px; height: 7px; border-radius: 50%; background: var(--mm-ok); flex: 0 0 7px; animation: mcpull-pulse 1.6s var(--ease) infinite; }\r\n.switch{\r\n  position: relative; width: 40px; height: 22px; flex: 0 0 40px; cursor: pointer;\r\n  border-radius: var(--r-full); border: 1px solid var(--mm-ctl-line); background: var(--mm-bg-3);\r\n  transition: background var(--t-base) var(--ease), border-color var(--t-base) var(--ease);\r\n}\r\n.switch::after{\r\n  content: \"\"; position: absolute; top: 1.5px; left: 2px; width: 16px; height: 16px;\r\n  border-radius: 50%; background: var(--mm-surface); box-shadow: var(--sh-sm);\r\n  transition: transform var(--t-base) var(--ease);\r\n}\r\n.switch[aria-checked=\"true\"]{ background: var(--mm-accent); border-color: var(--mm-accent); }\r\n.switch[aria-checked=\"true\"]::after{ transform: translateX(17px); }\r\n.switch:focus-visible{ outline: 2px solid var(--mm-accent); outline-offset: 2px; }\r\n\r\n/* ---------- 日志 ---------- */\r\n.logs{ padding: var(--sp-4) 0 0; }\r\n.logs details{ border: 1px solid var(--mm-line); border-radius: var(--r-ctl); overflow: hidden; }\r\n.logs summary{ list-style: none; cursor: pointer; padding: 10px var(--sp-3); display: flex; align-items: center; gap: var(--sp-2); font-size: 12.5px; font-weight: 600; background: var(--mm-surface); user-select: none; }\r\n.logs summary::-webkit-details-marker{ display: none; }\r\n.logs summary .chev{ transition: transform var(--t-base) var(--ease); margin-left: auto; color: var(--mm-muted); width: 14px; height: 14px; }\r\n.logs details[open] summary .chev{ transform: rotate(90deg); }\r\n.logs .body{ border-top: 1px solid var(--mm-line); background: var(--mm-bg-2); padding: var(--sp-2) 6px; max-height: 220px; overflow: auto; }\r\n.log-line{ display: flex; gap: 10px; align-items: baseline; font-size: 12px; padding: 5px 9px; border-radius: 6px; }\r\n.log-line:hover{ background: var(--mm-bg-3); }\r\n.log-line .ts{ font-family: var(--font-num); color: var(--mm-muted); flex: 0 0 auto; font-size: 11px; }\r\n.log-line .dd{ width: 6px; height: 6px; border-radius: 50%; flex: 0 0 6px; align-self: center; background: var(--mm-muted); }\r\n.log-line.ok .dd{ background: var(--mm-ok); }\r\n.log-line.warn .dd{ background: var(--mm-warn); }\r\n.log-line.act .dd{ background: var(--mm-accent); }\r\n.log-line.err .dd{ background: var(--mm-err); }\r\n.log-line .m{ color: var(--mm-text-1); }\r\n.log-empty{ color: var(--mm-muted); font-size: 12px; padding: var(--sp-2) 10px; }\r\n\r\n@media (max-width: 768px){\r\n  .mcpull-root{ padding: var(--sp-3); }\r\n  .inst-menu{ min-width: 260px; max-width: 92vw; }\r\n  .stage-card .meta{ gap: var(--sp-3); }\r\n  .step .lab{ font-size: 11px; }\r\n}\r\n@media (prefers-reduced-motion: reduce){\r\n  .mcpull-root *{ transition: none !important; animation: none !important; }\r\n  .btn .spin, .spin-lg{ animation: none; border-right-color: currentColor; }\r\n}";
